  "coptic_month_name_english" TEXT NOT NULL,
  "coptic_month_name_arabic" TEXT NOT NULL,
  PRIMARY KEY ("coptic_month", "coptic_day"),
  CHECK (((((coptic_month >= 1) AND (coptic_month <= 12)) AND ((coptic_day >= 1) AND (coptic_day <= 30))) OR ((coptic_month = 13) AND ((coptic_day >= 1) AND (coptic_day <= 6)))))
) STRICT;

